static bool requireAssignType(Instruction *I) {
  if (const auto *Intr = dyn_cast<IntrinsicInst>(I)) {
    switch (Intr->getIntrinsicID()) {
    case Intrinsic::invariant_start:
    case Intrinsic::invariant_end:
      return false;
    }
  }
  return true;
}

